        οᴏ[oо.o‌о] = ["\u0416а\u0440\u0435\u043D\u043e\u0435\40\u041c\u044f\u0441\u043E", "\u041f\u0440\u0435\u0432\u043e\u0441\u0445\u043E\u0434\u043D\u044b\u0439\40\u0441\u0442\u0435\u0439\u043a\54\40\u043f\u043e\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430", "\u0415\u0434\u0430\72\x20\x33\x35"];
