        οᴏ[oо.ⲟοoo‍] = ["\u041A\u0430\u043c\u0435н\u043d\u044b\u0439\x20\u0428\u043b\u0435\u043c", "\u0412\u044B\40\u0433\u043e\u0442\u043e\u0432\u044b\x20\u043a\x20\u0431\u0438\u0442\u0432\u0435\x21", "\u0417\u0430\u0449\u0438\u0442\u0430\40\u043E\u0442\x20\u0438\u0433\u0440\u043E\u043a\u043e\u0432\x3A\x20\x32", "\u0417\u0430\u0449\u0438т\u0430\40\u043E\u0442\40\u0436\u0438\u0432\u043e\u0442\u043d\u044B\u0445\x3a\x20\x38"];
        οᴏ[oо.ᴏ‌‍] = ["\u0417\u043E\u043b\u043e\u0442\u043e\u0439\40\u0428\u043b\u0435\u043c", "\u0422\u0430\u043A\u0436е\40\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d\40\u043a\u0430\u043A\40\u0448\u043B\u0435\u043C\40\u0436\u0435\u0441\u0442\u043E\u043a\u0438\u0445 \u043Bю\u0434\u0435\u0439", "\u0417\u0430\u0449\u0438\u0442\u0430\x20\u043e\u0442\40\u0438\u0433\u0440\u043e\u043A\u043E\u0432\72\x20\64", "\u0417\u0430\u0449\u0438\u0442\u0430\40\u043E\u0442\x20\u0436\u0438\u0432о\u0442\u043D\u044b\u0445\x3A\40\x31\x33"];
        οᴏ[oо.o‍oᴑ‌] = ["\u0410\u043B\u043c\u0430\u0437\u043D\u044B\u0439\x20\u0428\u043B\u0435\u043c", "\u041d\u0435\40\u0441\u043b\u0438\u0448\u043a\u043E\u043C\40\u0445\u0432\u0430\u0441\u0442\u0430\u0439\u0442\u0435\u0441\u044c", "\u0417\u0430\u0449\u0438\u0442\u0430\x20\u043Eт\40\u0438\u0433\u0440\u043E\u043A\u043E\u0432\x3A\x20\x35", "\u0417\u0430\u0449\u0438\u0442а\x20\u043e\u0442\x20ж\u0438\u0432\u043E\u0442\u043d\u044b\u0445\x3a\x20\61\x39"];
        οᴏ[oо.ᴏoоᴑo] = ["\u0410\u043c\u0435\u0442\u0438\u0441\u0442\u043e\u0432\u044B\u0439\u0020\u0428\u043B\u0435\u043c", "\u0422\u044b\x20\u0431\u043e\u043b\u044C\u0448\u0435\x20\u043d\u0438\u0447\u0435\u0433\u043E\40\u043D\u0435\x20\u0431\u043eи\u0448\u044c\u0441\u044f", "\u0417\u0430\u0449\u0438\u0442\u0430\x20о\u0442\40\u0438\u0433\u0440\u043E\u043A\u043E\u0432\x3a\x20\x36", "\u0417\u0430\u0449\u0438\u0442\u0430\u0020\u043E\u0442\x20\u0436\u0438\u0432\u043e\u0442\u043D\u044B\u0445\72\40\62\x33"];
        οᴏ[oо.oօoоⲟ] = ["\u0428\u043B\u0435\u043c\40\u0414\u0440\u0430\u043A\u043E\u043D\u0430", "\u0422\u044b\x20\u043F\u043e\u043a\u043E\u0440\u0438\u0448\u044c\40\u043C\u0438\u0440", "\u0417а\u0449\u0438\u0442\u0430\40\u043E\u0442\x20\u0438\u0433\u0440\u043e\u043a\u043e\u0432\72\40\x38", "\u0417\u0430\u0449\u0438\u0442\u0430\x20\u043E\u0442\40\u0436\u0438\u0432\u043E\u0442\u043d\u044B\u0445\u003A\40\x32\67"];
        οᴏ[oо.ᴏⲟοoo] = ["\u0428\u0430\u043F\u043a\u0430\x20\u0418\u0441\u0441л\u0435д\u043e\u0432\u0430\u0442\u0435\u043B\u044F", "\u0416\u0438\u0432\u043E\u0442\u043D\u044B\u0435\40\u043D\u0435\x20\u043E\u0431\u0440\u0430\u0449\u0430\u044e\u0442\x20\u043D\u0430\40\u0432\u0430\u0441\40в\u043Dи\u043C\u0430\u043d\u0438\u044f", "\u043d\u043E\40н\u0435\40\u0448\u0443\u043C\u0438\u0442\u0435\41", օᴏ[0X21E]];
        οᴏ[oо.ᴑooοᴏ] = ["\u0420\u043e\u0436\u0434\u0435\u0441\u0442\u0432е\u043D\u0441\u043a\u0430\u044F\40\u0428\u0430\u043F\u043a\u0430", "\u041E\u0445\55\u0445\u043E\x2D\u0445\u043E\54\40\u0421\u0447\u0430\u0441\u0442\u043b\u0438\u0432\u043e\u0433\u043e\u0020\u0420\u043Eж\u0434\u0435\u0441\u0442\u0432\u0430", օᴏ[542]];
        οᴏ[oо.ⲟօօοο] = ["\u0428\u0430\u043f\u043A\u0430\40\u042D\u043B\u044C\u0444\u0430", "\u041d\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0439\u0442\u0435\x20\u0441\u0435\u0431\u0435\u0020\u044d\u043a\u0441\u043f\u043B\u0443\u0430\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C\u0441\u044F\54\40\u0432\u0435\u0434\u044c\40\u0432\u044b\40\u043c\u0430\u043B\u0435н\u044c\u043a\u0438\u0439\40\u0441\u043d\u0435\u0436\u043D\u044B\u0439\40\u044D\u043B\u044c\u0444\41", օᴏ[0X21e]];
        οᴏ[oо.о‌o] = ["\u041A\u0430\u043F\u044E\u0448\u043Eн", "\u0412\u044b\40\u0440\u0430\u0437\u0431о\u0439\u043dи\u043a", "\u0412\u044B\u0020\u043c\u043e\u0436\u0435\u0442\u0435\x20\u0443\u043a\u0440\u0430\u0441т\u044C\40ч\u0442\u043e\55\u0442\u043e\x2C е\u0441\u043b\u0438", "\61\51\x20\u041D\u043E\u0447\u044C", "\62\x29\40\u0412ы\x20\u043D\u0438ч\u0435\u0433\u043e\x20н\u0435\x20\u043d\u043E\u0441\u0438\u0442\u0435", "\u0033\x29\u0415\u0441\u043b\u0438\x20\u0432\u0430\u0441\40\u043d\u0435\40\u0442\u0440\u043e\u043D\u0443\u043b\u0438\40\u0432\u0020\u0442\u0435\u0447\u0435\u043D\u0438\u0435\40\u0432\u043e\u0441\u044C\u043C\u0438\x20\u0441\u0435\u043A\u0443\u043D\u0434", "\64\x29\x20\u0412\u044B \u043D\u0435\x20\u0440\u044f\u0434\u043E\u043C\40\u0441\x20о\u0433\u043D\u0451\u043C", "\65\x29\x20\u0412\u044B\40\u043D\u0435\40\u043c\u043e\u0436\u0435\u0442\u0435\x20\u043d\u0438\u0447\u0435\u0433\u043e\40\u0443\u043a\u0440\u0430\u0441\u0442\u044c\40у\u0020\u043a\u0440\u0435\u0441\u0442\u044c\u044f\u043d\u0441\u043a\u043E\u0439\40\u0442\u0443\u043D\u0438\u043A\u0438", օᴏ[0X21e]];
        οᴏ[oо.ᴑᴑօ] = ["\u0422\u0435\u043f\u043B\u044B\u0435\40\u041D\u0430\u0443\u0448\u043D\u0438\u043a\u0438", "\u041a\u0430\u043A\u0430\u044F\55\u0442\u043E\40\u043C\u0430\u043B\u0435\u043d\u044c\u043a\u0430\u044f\x20\u0448\u0430\u043f\u043A\u0430\x2E", օᴏ[01036]];
        οᴏ[oо.ᴑ‍ⲟ] = ["\u0428\u0430\u043f\u043a\u0430", "\u0422\u0430\u043a\x20\u0436\u0435\x20\u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F\40\u043F\u0430\u043b\u044c\u0442\u043e\u043C\56", օᴏ[0X21E]];
        οᴏ[oо.ⲟοᴑоо] = ["\u0417\u0438\u043C\u043D\u0438\u0439\40\u0428\u0430\u0440\u0444\x20\u0438\x20\u0428\u0430\u043F\u043A\u0430", "\u041e\u0447\u0435\u043D\u044C\x20\u043A\u043E\u043c\u0444\u043E\u0440\u0442\u043D\u043E", "\u041eч\u0435\u043D\u044C \u0442\u0435\u043f\u043B\u043E"];
        οᴏ[oо.о‍ⲟ] = ["\u041A\u0440\u0435\u0441\u0442\u044C\u044F\u043D\u0441к\u0430\u044f\40\u0422\u0443\u043d\u0438\u043a\u0430", "\u0412\u0430\u0448и\x20\u0440\u0430\u0441\u0442\u0435\u043d\u0438\u044F\40\u0440\u0430\u0441\u0442\u0443\u0442\x20\u0431\u044B\u0441\u0442\u0440\u0435\u0435", օᴏ[01036]];
        οᴏ[oо.о‍o] = ["\u0417\u0438\u043c\u043d\u0438\u0439\x20\u041A\u0430\u043F\u044E\u0448\u043E\u043D", "\u0412\u044B\x20\u043C\u043E\u0436\u0435\u0442\u0435\40\u0443\u043A\u0440\u0430\u0441\u0442\u044c \u0447\u0442\u043E\x2d\u0442\u043e\x2C\40\u0435\u0441\u043b\u0438", "\55\40\u041d\u043E\u0447\u044c", "\x2d\40\u0412\u044B\x20\u043d\u0438\u0447\u0435\u0433\u043E\40\u043d\u0435\x20\u043D\u043E\u0441\u0438\u0442\u0435", "\u002d\x20\u0415\u0441\u043B\u0438\x20\u0432\u0430\u0441\40\u043D\u0435\40\u0442\u0440\u043E\u043D\u0443\u043B\u0438\x20\u0432\40\u0442\u0435\u0447\u0435\u043d\u0438\u0435\x20\u0447е\u0442\u044B\u0440ё\u0445\40\u0441\u0435\u043a\u0443\u043D\u0434", "\55\u0020\u0412\u044b\40\u043D\u0435\40\u0440\u044F\u0434\u043e\u043c\40\u0441\40\u043e\u0433\u043d\u0451\u043C", "\55\40\u0412\u044B\40\u043D\u0435\x20м\u043e\u0436\u0435\u0442\u0435\x20\u043D\u0438\u0447\u0435\u0433\u043E\x20\u0443\u043a\u0440\u0430\u0441\u0442\u044c\x20\u0443\40\u043a\u0440\u0435\u0441\u0442\u044C\u044F\u043d\u0441\u043A\u043e\u0439 \u0442\u0443\u043D\u0438\u043Aи", օᴏ[01036]];
        οᴏ[oо.ⲟ‌oⲟ‌] = ["\u0417и\u043c\u043D\u044F\u044F\x20\u041a\u0440\u0435\u0441\u0442\u044C\u044F\u043D\u0441\u043a\u0430\u044f\40\u0422\u0443\u043d\u0438\u043A\u0430", "\u0412\u0430\u0448\u0438 \u0440\u0430\u0441\u0442\u0435\u043d\u0438\u044F\40\u0440\u0430\u0441\u0442\u0443\u0442\x20\u0431\u044B\u0441\u0442\u0440\u0435\u0435", օᴏ[0X21e]];
        οᴏ[oо.ᴏ‌о] = ["\u0410\u043A\u0432\u0430\u043B\u0430\u043d\u0433", "\u0412\u044b\40\u0431\u044B\u0441\u0442\u0440\u0435\u0435\x20\u043f\u0435\u0440\u0435\u0434\u0432\u0438\u0433\u0430\u0435\u0442\u0435\u0441\u044c\x20\u043f\u043E\40\u0432о\u0434\u0435", "\u0422\u0435\u043f\u043b\u043E\40\u0432\u0020\u0432\u043e\u0434\u0435", "\u0417\u0430\u0449\u0438\u0442\u0430\40\u043E\u0442\x20\u0438\u0433\u0440\u043E\u043a\u043e\u0432\72\40\x32\x2c\x20\u0417\u0430\u0449\u0438\u0442\u0430\u0020\u043e\u0442\x20\u0436\u0438в\u043E\u0442\u043d\u044b\u0445\72\x20\x38"];
        οᴏ[oо.oоᴑo‌] = ["\u0421у\u043F\u0435\u0440\40\u0410\u043a\u0432\u0430\u043B\u0430\u043d\u0433", "\u0412\u044b\40\u043E\u0447\u0435\u043D\u044C\u0020\u0431\u044Bс\u0442р\u043e\x20\u043f\u0435\u0440\u0435\u0434\u0432\u0438\u0433а\u0435\u0442\u0435\u0441\u044c\40\u043f\u043E\x20\u0432\u043e\u0434\u0435", "\u0422\u0435\u043f\u043b\u043e\40\u0432\40\u0432\u043e\u0434\u0435", օᴏ[422]];
        οᴏ[oо.ⲟоо‍օ] = ["\u0428\u0430\u0440\x20\u0414\u0440\u0430\u043a\u043Eн\u0430", "\u0414\u0430\u0451\u0442\u0441\u044F\x20з\u0430\x20\u043A\u0432\u0435\u0441\u0442"];
        οᴏ[oо.ᴑоᴏ‌о] = ["\u0421\u0435\u0440\u0434\u0446\u0435\x20\u0414\u0440\u0430\u043aо\u043d\u0430", "\u041F\u0440\u0435\u0432\u0440а\u0449\u0430\u0435\u0442\x20\u0432а\u0441\40\u0432\40\u043F\u0440\u0438\u0437\u0440\u0430\u043a\u0430\x20\u043f\u043E\u0441\u043b\u0435\x20\u0441\u043c\u0435\u0440\u0442\u0438\x21", "\u0412\u044B\40\u043f\u0440\u0438\u0437\u0440\u0430\u043A\x20\u043D\u0430\x20\x36\x30\x20\u0441\u0435\u043A\u0443\u043D\u0434", "Н\u0430\u0439\u0434\u0438\u0442\u0435\x20\u043A\u0430\u043c\u0435\u043D\u044C\40\u0432\u043E\u0441\u043A\u0440\u0435\u0448\u0435\u043d\u0438\u044f"];
        οᴏ[oо.ⲟoⲟօо] = ["\u0417\u0435\u043b\u0451\u043d\u044B\u0439\x20\u0414\u0440\u0430\u0433\u043e\u0446\u0435\u043D\u043D\u044B\u0439\40\u041A\u0430\u043c\u0435\u043d\u044c", "\u0412\u044B\40\u0431\u0435\u0437\40\u0447\u0438\u0442\u043e\u0432\x2c\x20\u043F\u0440\u0430\u0432и\u043B\u044c\u043d\u043E\x3f"];
        οᴏ[oо.oоᴑοᴏ] = ["\u041e\u0440\u0430\u043d\u0436\u0435\u0432\u044b\u0439\40\u0414\u0440\u0430\u0433\u043e\u0446\u0435\u043D\u043D\u044b\u0439\x20\u041a\u0430\u043C\u0435\u043D\u044C", "\u0422\u043E\u043B\u044c\u043A\u043e\40\u043d\u0430\u0441\u0442\u043e\u044F\u0449ий\x20\u043f\u0438\u0440\u0430\u0442\40\u043D\u0430\u0439\u0434\u0451\u0442\x20\u044D\u0442\u043e\x21"];
        οᴏ[oо.օᴏⲟⲟօ] = ["\u0421\u0438\u043d\u0438\u0439\x20\u0414\u0440\u0430\u0433\u043e\u0446\u0435\u043d\u043d\u044B\u0439\x20\u041a\u0430\u043C\u0435\u043d\u044C", "\u0414\u043B\u044F\40\u043e\u0447\u0435\u043d\u044c\x20\u0434\u043e\u0431р\u044b\u0445\x20\u043b\u044e\u0434\u0435\u0439"];
        οᴏ[oо.oᴑⲟoо] = ["\u0417\u0435\u043B\u0435\u043D\u0430\u044F\x20\u043a\u043E\u0440\u043e\u043D\u0430", "\u0412\u044b \u043B\u0435\u0447\u0438\u0442\u0435\x20\u0441\u0435\u0431\u044F\40\u043e\u0447\u0435\u043D\u044C\40\u0431\u044b\u0441\u0442\u0440\u043e", "\u041B\u0435\u0447\u0438\u0442\72\x20\64\60", օᴏ[422]];
        οᴏ[oо.ooօoⲟ] = ["\u041e\u0440\u0430\u043d\u0436\u0435\u0432\u0430\u044F \u041A\u043E\u0440\u043Eн\u0430", "\u0412\u0430\u043C\40\u043e\u0447\u0435\u043d\u044C\40п\u043E\u0432\u0435\u0437\u043b\u043e", օᴏ[0X1a6]];
        οᴏ[oо.ᴏоοᴏο] = ["\u0421\u0438\u043d\u044F\u044f\40\u041A\u043eр\u043E\u043D\u0430", "\u041Aа\u043A\40\u0442\u043E\u043B\u044c\u043aо\40\u0432\u044b\40у\u043C\u0440\u0451\u0442е\x2C\40\u0432\u044B\40\u0441\u0442\u0430\u043d\u0435\u0442\u0435\40\u043f\u0440\u0438\u0437\u0440\u0430\u043a\u043e\u043c", "\u041D\u043e\x20\u0432\u044B\x20\u043F\u043E\u0442\u0435р\u044F\u0435\u0442\u0435\40\u0441\u0432\u043e\u0451\x20\u043E\u0440\u0443ж\u0438\u0435", օᴏ[0X1A6]];
        οᴏ[oо.ооοᴏ‌] = ["\u0412\u0435\u0434\u0440\u043e", "\u0418\u0441\u043f\u043E\u043b\u044C\u0437\u0443\u0435\u0442\u0441\u044F\x20\u0434\u043b\u044f\x20з\u0430\u043f\u043E\u043b\u043d\u0435\u043d\u0438\u044f\40\u043a\u043E\u043b\u043E\u0434\u0446\u0430", "\u041e\u0434\u043d\u043e\x20\u0432\u0435\u0434\u0440\u043e\40\u0440\u0430\u0432\u043D\u044f\u0435\u0442\u0441\u044F\x20\u0434\u0432\u0435\u043d\u0430\u0434\u0446\u0430\u0442\u0438\x20\u0431\u0443\u0442\u044b\u043B\u043A\u0430\u043C"];
        οᴏ[oо.ᴏ‍οоo] = ["\u041F\u0443\u0441\u0442\u043e\u0435\x20\u0432\u0435д\u0440\u043e", "\u0412\u0430\u043C\x20\u043d\u0430\u0434\u043E\x20\u0437\u0430\u043f\u043e\u043B\u043d\u0438\u0442\u044C\x20\u044d\u0442\u043e\x20\u0432\u0435\u0434р\u043E\40\u0432\u043E\u0437л\u0435\40\u0432о\u0434\u044B"];
        οᴏ[oо.ᴑᴏο] = ["\u0411\u0443\u0442\u044B\u043b\u043A\u0430", "\u041f\u043e\u0437\u0432\u043e\u043B\u044f\u0435\u0442\x20\u043F\u0438ть\x20\u0432\u043E\u0434\u0443\40\u0432\x20\u043B\u044E\u0431\u043e\u043C\40\u043C\u0435\u0441\u0442\u0435", "\u0412\u043e\u0434\u0430\72\40\x35\60"];
        οᴏ[oо.οоᴑoᴑ] = ["\u041Fу\u0441\u0442\u0430\u044F\40\u0431\u0443\u0442\u044B\u043B\u043a\u0430", "\u0412\u044B\x20\u043c\u043E\u0436\u0435\u0442\u0435\x20\u0437\u0430\u043F\u043e\u043b\u043D\u0438\u0442\u044c\x20\u0431\u0443\u0442\u044b\u043B\u043A\u0443\x20\u0432\u043E\u0437\u043b\u0435\40\u0432\u043e\u0434\u044B"];
        οᴏ[oо.οօᴏ‍ᴏ] = ["\u041f\u0443\u0441\u0442\u0430\u044f\u0020\u041B\u0435\u0439\u043A\u0430", "\u0412\u044B\x20\u043C\u043E\u0436\u0435т\u0435\40\u0437\u0430\u043f\u043e\u043B\u043D\u0438\u0442\u044C\40\u043B\u0435й\u043a\u0443\x20\u0432\u043E\u0437\u043b\u0435 \u0432\u043E\u0434ы"];
        οᴏ[oо.ⲟ‌ᴑ] = ["\u041bе\u0439к\u0430", "\u041f\u043e\u0437\u0432\u043E\u043b\u044F\u0435\u0442\x20\u043f\u043E\u043B\u0438\u0432\u0430\u0442\u044c\x20р\u0430\u0441\u0442\u0435\u043d\u0438\u044f", "\u0423\u0440\u043e\u043D\72\40\x31"];
        οᴏ[oо.оᴑօ] = ["\u0420\u044E\u043a\u0437\u0430\u043a", "\u0411\u043E\u043B\u044C\u0448е\x20\u043c\u0435\u0441\u0442\u0430\40\u0434\u043B\u044F\x20\u0432\u0430\u0448\u0438\u0445\x20\u043F\u0440\u0435\u0434\u043c\u0435т\u043E\u0432\41"];
        οᴏ[oо.οοo‍‌] = ["\u0411\u0443\u043C\u0430\u0433\u0430", "\u0418\u0441\u043F\u043E\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044F\40\u043fр\u0438\40\u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438\x20\u043a\u043D\u0438\u0433\u0438"];
        οᴏ[oо.оօᴑ] = ["\u041A\u043d\u0438\u0433\u0430", "\u0421\u043Eк\u0440\u0430\u0449\u0430\u0435\u0442\x20\u0432\u0440\u0435\u043c\u044F \u0438\u0437\u0433\u043E\u0442о\u0432\u043b\u0435\u043D\u0438\u044F\x20\u043f\u0440\u0435\u0434\u043Cе\u0442\u043e\u0432", "\u0414\u043eл\u0436\u043d\u043e\x20\u0431\u044b\u0442\u044c\x20\u043E\u0434\u0435\u0442\u043E\x20\u0434\u043B\u044F\40\u0440\u0430б\u043E\u0442\u044B", "\u0423\u0440\u043e\u043d\x3A\x20\x31"];
        οᴏ[oо.ᴏοоⲟօ] = ["\u0411\u0438\u043D\u0442", "\u0412\u043E\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442\x20\u0432\u0430\u0448\u0435\x20\u0437\u0434\u043E\u0440\u043E\u0432\u044c\u0435\40\u0431\u044b\u0441\u0442\u0440\u0435\u0435", "\u041bе\u0447\u0438\u0442\72\40\x33\60", "\u042d\u0444\u0444\u0435\u043a\u0442\x3a\40\x35"];
        οᴏ[oо.о‍о] = ["\u0417\u0430\u043c\u043E\u043a", "\u041f\u043e\u0437\u0432\u043e\u043B\u044F\u0435\u0442\x20\u0432\u0430\u043c\40\u0437\u0430\u043A\u0440\u044B\u0442\u044c\u0020\u0432\u0430\u0448\40\u0441\u0443\u043D\u0434\u0443к"];
        οᴏ[oо.օ‌оᴑᴏ] = ["\u041A\u043B\u044E\u0447", "\u0414\u0430\u0451\u0442\40\u0432\u0430\u043C\x20\u043E\u0442к\u0440\u044b\u0442\u044c\x20\u043E\u0434\u0438\u043D\x20\u0437\u0430\u043f\u0435р\u0442ы\u0439\x20\u0441\u0443\u043D\u0434\u0443\u043A"];
        οᴏ[oо.oᴏᴏ] = ["\u0422\u043E\u0442\u0435\u043C", "\u041F\u043e\u0437\u0432\u043e\u043B\u044f\u0435\u0442\u0020\u0432\u0430\u043c\40\u0441\u043e\u0437\u0434\u0430\u0442\u044C\x20\u043A\u043E\u043C\u0430\u043d\u0434\u0443", "\u0421о\u0432\u043c\u0435\u0441\u0442\u043D\u043e\u0435\40\u0438\u0441\u043f\u043e\u043B\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435\40\u0434\u0432\u0435\u0440\u0435\u0439\40\u0438\40\u0441\u0443\u043d\u0434\u0443\u043a\u043e\u0432", "\u0412\u0440\u0435\u0434\u043D\u043E\u0435\x20\u0437\u0434\u0430\u043d\u0438\u0435\40\u043d\u0435\40\u043f\u043E\u0432\u0440\u0435\u0434\u0438\u0442\x20\u0432\u0430\u0448\u0435\u0433\u043E\40\u0434\u0440\u0443\u0433\u0430"];
        οᴏ[oо.ⲟᴑο] = ["\u041c\u043e\u0441\u0442", "\u041e\u0447\u0435\u043D\u044C\x20\u043f\u043e\u043b\u0435\u0437\u043d\u043E\40\u043d\u0430\x20\u0432\u043E\u0434е", "\u041F\u043e\u0437\u0432\u043eл\u044F\u0435\u0442\x20\u0432а\u043c\40\u043f\u0438т\u044C\40\u0431\u0435\u0437\x20\u043F\u043e\u0442\u0435\u0440\u0438\x20\u0432о\u0437\u0434\u0443\u0445\u0430", "\u041F\u0435\u0440\u0435\u0434\u0432и\u0433\u0430\u0435\u0442\u0435\u0441\u044c\x20\u0431\u044b\u0441\u0442\u0440\u0435\u0435\40\u043F\u043e \u0432\u043E\u0434\u0435"];
        οᴏ[oо.ⲟⲟ‍] = ["\u0422а\u0431\u043b\u0438\u0447\u043a\u0430", "\u041e\u0441\u0442\u0430\u0432\u044c\u0442\u0435\x20\u0441\u043eо\u0431\u0449\u0435\u043d\u0438е\x20\u0434\u0440\u0443\u0433\u0438\u043C", "П\u0440\u043E\u0447\u043D\u043E\u0441т\u044c\72\40\62\60\x30"];
        οᴏ[oо.οᴑⲟ] = ["\u041a\u0440\u044b\u0448\u0430", "\u041d\u0435\u043C\u043d\u043E\u0433\u043e\40\u0441\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0020в\u0430с\x20\u0438\x20\u0441\u043E\u0433\u0440\u0435\u0432\u0430\u0435\u0442\x21"];
        οᴏ[oо.ᴑοᴏ] = ["\u041a\u043e\u043B\u043E\u0434\u0435\u0446", "\u041f\u043e\u0437\u0432\u043E\u043b\u044f\u0435\u0442\x20\u0437\u0430\u043f\u043e\u043B\u043D\u0438т\u044C\x20\u0431\u0443\u0442\u044b\u043b\u043a\u0443", օᴏ[82]];
        οᴏ[oо.ⲟᴑ‌] = ["\u0414\u0435\u0440\u0435\u0432\u044F\u043d\u043D\u0430\u044f\x20\u0421\u0442\u0435\u043d\u0430", "\u042D\u0442\u043E\x20\u043F\u0440\u043E\u0441\u0442\u043E\40\u0441\u0442\u0435\u043D\u0430", օᴏ[82]];
        οᴏ[oо.ᴑⲟօ] = ["\u041a\u0430\u043c\u0435\u043d\u043Dа\u044f\40\u0421\u0442\u0435\u043d\u0430", "\u042d\u0442\u043e\x20\u043d\u0435\u043C\u043D\u043E\u0433\u043E\40\u043F\u043E\u0441\u0435\u0440\u044C\u0435\u0437\u043D\u0435\u0435\56", "\u041F\u0440\u043E\u0447\u043D\u043E\u0441\u0442\u044c\72\x20\61\x35\60\x30"];
        οᴏ[oо.ⲟօο] = ["\u0417\u043e\u043B\u043eт\u0430\u044f\x20\u0421\u0442\u0435н\u0430", "\u0417\u043e\u043B\u043e\u0442\u043e\x20\u043D\u0430\x20\u0432\u0430\u0448\u0438\u0445\40\u0441\u0442\u0435\u043d\u0430х\77\x20\u041E\u043d\u0430\40\u043E\u0441\u043b\u0435\u043F\u043B\u044f\u0435\u0442\x2E", օᴏ[0314]];
        οᴏ[oо.ᴏⲟⲟ] = ["\u0410\u043Bм\u0430\u0437н\u0430я\40\u0421\u0442\u0435\u043d\u0430", "\u041E\u0447\u0435\u043D\u044C\40\u0431\u043b\u0435\u0441\u0442\u0438\u0442\x2C\40\u0441\u043Bе\u0434\u0438\u0442\u0435\x20\u0437\u0430\x20\u0432\u0430\u0448и\u043C\u0438\40\u0433\u043B\u0430\u0437\u0430\u043C\u0438", "\u041f\u0440\u043E\u0447\u043d\u043E\u0441\u0442\u044C\x3A\x20\x325\x30\60"];
        οᴏ[oо.οᴑᴑ] = ["\u0410\u043c\u0435\u0442\u0438\u0441\u0442\u043e\u0432\u0430\u044F\x20с\u0442\u0435н\u0430", "\u0412\u044B\u0020\u0434\u043Eл\u0436\u043d\u044B\x20\u0431\u044B\u0442\u044C\40\u0441\u043b\u0438\u0448\u043A\u043E\u043c\x20\u043D\u0430\u043f\u0443\u0433\u0430\u043d\u044b\x2C\40\u0447\u0442\u043E\u0431ы\x20\u0443\u0439\u0442\u0438\x21", "\u041fр\u043E\u0447\u043d\u043e\u0441\u0442\u044c: \x33\65\x30\60"];
        οᴏ[oо.ᴑ‌օ] = ["\u0414\u0435\u0440\u0435\u0432\u044f\u043d\u043D\u0430\u044f\x20\u0421\u0442\u0435\u043d\u0430\u0020\u0441\x20\u0428\u0438п\u0430\u043C\u0438", "\u041c\u043E\u0436\u0435\u0442\x20\u043d\u0430\u043d\u043E\u0441\u0438\u0442\u044C\x20\u0443\u0440\u043e\u043D\u0020\u0432\u0440\u0430\u0433\u0430\u043C", "\u0423\u0440\u043E\u043d\u003A\x20\61\x30\x2C\40\u0423\u0440\u043e\u043d\x20\u0437\u0430 \u043e\u0434\u0438\u043D\40\u0443\u0434\u0430\u0440\72\40\62", "\u041F\u0440\u043E\u0447\u043d\u043E\u0441\u0442\u044c\72\40\x31\x35\x30"];
        οᴏ[oо.оοⲟ] = ["\u041A\u0430\u043c\u0435\u043D\u043D\u0430\u044f\x20\u0421\u0442е\u043D\u0430\40\u0441\x20\u0428\u0438\u043fа\u043C\u0438", "\u042f\x20\u043d\u0435\40\u0445\u043E\u0442е\u043b\40\u0431\u044B\40\u0431\u044B\u0442\u044C\40\u0432\u0430ш\u0438\u043c\x20\u0432\u0440\u0430\u0433\u043e\u043c", "\u0423\u0440\u043E\u043D\x3A\40\62\x30", "\u0423\u0440\u043E\u043d\x20\u0437\u0430\x20\u043e\u0434\u0438\u043d\x20\u0443\u0434\u0430\u0440\x3a\x20\x33", "\u041F\u0440\u043E\u0447\u043D\u043E\u0441\u0442\u044c\72\u00203\x30\60"];
        οᴏ[oо.οⲟᴑ] = ["\u0417\u043e\u043b\u043eт\u0430\u044f\x20\u0421\u0442\u0435\u043D\u0430\40\u0441\x20\u0428\u0438\u043F\u0430\u043C\u0438", "В\u044B\x20\u043E\u0447\u0435\u043D\u044C\40\u0436\u0435\u0441\u0442\u043e\u043A\u0438\56", "\u0423\u0440\u043E\u043d\72\x20\x33\x30", "У\u0440\u043E\u043D\x20\u0437\u0430\40\u043e\u0434\u0438\u043D\40\u0443\u0434\u0430\u0440\72\x20\63", "\u041F\u0440\u043e\u0447\u043d\u043e\u0441\u0442\u044C\x3a\x20\66\x30\x30"];
        οᴏ[oо.օоо] = ["\u0410л\u043C\u0430\u0437\u043d\u0430\u044F\40\u0421\u0442\u0435\u043D\u0430\40\u0441\u0020\u0428\u0438\u043F\u0430\u043C\u0438", "\u0412\u0430\u043C\40\u043D\u0435\40\u043d\u0440\u0430\u0432\u0438\u0442\u0441\u044f\x20\u0438\u043C\u0435\u0442\u044C\x20\u043A\u043E\u043C\u043f\u0430\u043D\u0438\u044E\56", "\u0423\u0440\u043e\u043D\u003a\40\x34\x30", "\u0423\u0440\u043E\u043D\x20\u0437\u0430\40\u043e\u0434\u0438\u043D\x20\u0443\u0434\u0430р:\40\64", "П\u0440\u043e\u0447\u043d\u043E\u0441\u0442\u044C\72\40\61\x32\60\x30"];
        οᴏ[oо.ᴑ‍ᴏ] = ["\u0410\u043c\u0435\u0442\u0438\u0441\u0442\u043E\u0432\u0430\u044F\40\u0421\u0442\u0435\u043d\u0430\x20\u0441\40\u0428\u0438\u043f\u0430\u043C\u0438", "\u041A\u0430\u043a\u043e\u0433\u043e\40\u0447\u0435\u0440та\x2C\x20\u0447\u0442\u043e\u0020\u0432\u0430\u0448\u0438\x20\u0441\u043e\u0441\u0435\u0434\u0438\x20\u0441д\u0435\u043B\u0430\u043B\u0438\x20с\x20в\u0430м\u0438\77", "\u0423\u0440\u043E\u043D\u003a\x20\x35\u0030", "\u0423\u0440\u043E\u043d\40\u0437\u0430\40\u043e\u0434и\u043d\x20\u0443\u0434\u0430\u0440\72\x20\64", "\u041F\u0440\u043Eч\u043d\u043E\u0441\u0442\u044c\x3A\40\62\64\60\x30"];
        οᴏ[oо.ⲟ‍o] = ["\u0414\u0435\u0440\u0435\u0432\u044F\u043D\u043D\u0430я\40\u0414\u0432\u0435\u0440\u044C", "\u041C\u043e\u0436\u0435\u0442\40\u0431\u044b\u0442\u044c\40\u043e\u0442\u043A\u0440\u044b\u0442\u0430\40\u0438\40\u0437\u0430\u043a\u0440\u044B\u0442\u0430\40\u0432\u0430\u043C\u0438\40\u0438\u043B\u0438 \u0434\u0440\u0443\u0437\u044c\u044f\u043c\u0438", օᴏ[0122]];
        οᴏ[oо.ο‌‍] = ["\u041A\u0430\u043c\u0435\u043D\u043d\u0430\u044F\x20\u0414\u0432\u0435\u0440\u044c", "\u0411\u043E\u043b\u0435\u0435\40\u0441\u0435\u0440\u044Cе\u0437\u043D\u0430я\x20\u0438\x20\u0441\u0438\u043b\u044c\u043D\u0430\u044f\40\u0434\u0432\u0435\u0440ь", "\u041f\u0440\u043E\u0447\u043Dо\u0441\u0442\u044C\x3a\40\61\x35\x30\x30"];
        οᴏ[oо.ⲟoο] = ["\u0417\u043e\u043B\u043E\u0442\u0430\u044f\40\u0414\u0432\u0435\u0440ь", "\u0412\u044b\x20\u043F\u0435\u0440\u0435\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0435\x20\x22\u042D\u043b\u044c \u0414\u043e\u0440\u0430\u0434\u043e\x3f\42", օᴏ[204]];
        οᴏ[oо.ᴏ‌ᴏ] = ["\u0410\u043B\u043C\u0430\u0437\u043d\u0430\u044F\40\u0414\u0432\u0435\u0440\u044C", "\u0414\u043b\u044f\40\u0440\u043E\u0441\u043a\u043E\u0448\u043D\u043E\u0433\u043E\40\u0434\u043E\u043C\u0430", "\u041F\u0440\u043e\u0447\u043D\u043E\u0441\u0442\u044c\72\40\x32\x35\60\60"];
        οᴏ[oо.о‍օ] = ["\u0410\u043C\u0435\u0442\u0438\u0441\u0442о\u0432\u0430\u044f\x20\u0414\u0432\u0435\u0440\u044c", "\u0412\u0430\u0448\40\u0434\u043E\u043c\x20\u0432\40\u0431\u0435\u0437\u043e\u043F\u0430\u0441\u043d\u043e\u0441\u0442\u0438\77", "\u041F\u0440\u043E\u0447н\u043e\u0441\u0442\u044c\x3A\x20\63\x30\60\60"];
        οᴏ[oо.ᴑᴏⲟ] = ["\u041F\u0435\u0447\u044c", "\u0421\u043e\u0433\u0440\u0435\u0432\u0430\u0435\u0442", "\u0422\u0440\u0430\u0442\u0438\u0442\40\u0434\u0435\u0440\u0435\u0432\u043E\x20\u043A\u0430\u0436\u0434\u044B\u0435\40\x35\40\u0441\u0435\u043A\u0443\u043d\u0434", օᴏ[0122]];
        οᴏ[oо.ᴑᴑо] = ["\u041c\u0435\u043B\u044c\u043d\u0438\u0446\u0430", "\u041C\u043E\u0436\u0435\u0442\40\u0441\u0434\u0435\u043b\u0430\u0442\u044C\x20\u043c\u0443\u043a\u0443\x20\u0438\u0437\40\u043f\u0448\u0435\u043D\u0438ц\u044b", "\u0422\u0440\u0435\u0431\u0443\u0435\u0442\40\65\u0020\u0441\u0435\u043A\u0443\u043D\u0434\40\u0434\u043b\u044F\x20\u043F\u043E\u043b\u0443\u0447\u0435\u043d\u0438\u044f\x20\u043C\u0443\u043a\u0438", "\u0414\u0430\u0451\u0442\40\u043e\u0447\u043A\u0438\x20\u043F\u0440\u0438\40\u0440\u0430\u0431\u043E\u0442\u0435", օᴏ[204]];
        οᴏ[oо.օ‍о] = ["\u0425\u043b\u0435\u0431\u043D\u0430\u044f\40\u041F\u0435\u0447\u044c", "\u041F\u043e\u0437\u0432\u043E\u043bя\u0435\u0442\x20\u0433\u043E\u0442\u043e\u0432\u0438\u0442\u044C\40\u0445\u043b\u0435\u0431\40\u0438\u0437\40\u043c\u0443\u043a\u0438", "\u0422\u0440\u0435\u0431\u0443\u0435\u0442\x20\x31\x30\x20\u0441\u0435\u043A\u0443\u043d\u0434\x20\u0434\u043B\u044f\x20\u043f\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F\40\u0445\u043b\u0435\u0431\u0430", "\u0414\u0430\u0451т\40\u043E\u0447\u043A\u0438\40\u043F\u0440\u0438\40\u0440\u0430\u0431\u043e\u0442\u0435", օᴏ[204]];
        οᴏ[oо.ᴏօο] = ["\u041A\u0430\u043C\u0435\u043d\u044C\x20\u0412\u043e\u0441\u043A\u0440е\u0448\u0435\u043D\u0438\u044f", "\u042d\u0442\u043E \u043c\u0430\u0433\u0438\u044f", "\u0412\u043E\u0441\u043a\u0440\u0435\u0448\u0430\u0435\u0442\x20\u0432\u0430\u0441\u002c\40\u0435\u0441\u043b\u0438 \u0432\u044b\40\u043f\u0440\u0438\u0437\u0440\u0430\u043A", "\u0412\u044b\x20\u043f\u043e\u0442\u0435\u0440\u044F\u0435\u0442\u0435\40\u0441\u0432\u043e\u0451\40\u043e\u0440\u0443\u0436\u0438\u0435", "\u041f\u0440\u043e\u0447\u043D\u043E\u0441\u0442\u044c\72\40\x32\x300"];
        οᴏ[οⲟօ.ᴑoᴏo‍] = "\u0412\u044B\x20\u043d\u0435\x20\u043C\u043E\u0436\u0435\u0442\u0435\40\u0437\u0430й\u0442\u0438\40\u043d\u0430\x20\u044d\u0442о\u0442\x20\u0441\u0435\u0440\u0432\u0435\u0440";
        οᴏ[οⲟօ.о‌ᴏοο] = "\u0412\u044B\u0433\u043D\u0430\u043D\u044b\x3a\x20";
        οᴏ[οⲟօ.ооooо] = "\u0412\u0430\u0448 \u043A\u043b\u044e\u0447\x20\u0443\u0436е\40\u0438\u0441\u043f\u043e\u043b\u044C\u0437\u0443\u0435\u0442\u0441\u044F\40\u043A\u0435\u043C\x2d\u0442\u043e";
        οᴏ[οⲟօ.οoօօо] = "\u0412\u0430\u0448\40\u043a\u043b\u044E\u0447\x20\u043d\u0435\u043F\u0440\u0430\u0432\u0438\u043bь\u043d\u044B\u0439";
        οᴏ[οⲟօ.ᴑᴑᴏ‍ᴏ] = "\u0423\x20\u0432\u0430\u0441\40\u0441\u0442\u0430\u0440\u0430\u044F\40в\u0435\u0440\u0441\u0438\u044F\u002C\u0020\u0432\u0430\u043c\x20\u043d\u0443ж\u043dо\x20\u043E\u0447\u0438\u0441\u0442\u0438\u0442\u044c\x20\u043A\u0435\u0448";
        οᴏ[οⲟօ.ⲟoо‍ο] = "\u0420\u0435\u0441ур\u0441\u043Eв\u0020\u0431\u043e\u043B\u044C\u0448е\40\u043D\u0435\u0442";
