        οᴏ[οⲟօ.оoоᴑօ] = "\x20\u0434\u043D\u0435\u0439";
        οᴏ[οⲟօ.oᴑoⲟо] = "\u0412\u044b\40\u0443\u043C\u0435\u0440\u043b\u0438\40\x3b\55\x3B";
        οᴏ[οⲟօ.ᴑooⲟⲟ] = "\u0421\u0435\u0440\u0432\u0435\u0440\40\u043D\u0435\40\u043C\u043E\u0436е\u0442\40\u043d\u0430\u0439\u0442и\x20\u0442\u043e\u0447\u043a\u0443\x20\u0441\u043F\u0430\u0432\u043d\u0430\x21\40\u0421\u043F\u0430\u043C\u044c\u0442\u0435\40\u043aн\u043E\u043f\u043A\u0443\x20\u0438\u0433\u0440\u0430\u0442\u044c\x21";
        οᴏ[οⲟօ.oօᴏ‍о] = "С\u0435\u0440\u0432ер\x20\u0437\u0430\u043F\u043E\u043B\u043d\u0435\u043d\x21 \u0421\u043F\u0430\u043c\u044c\u0442\u0435\40к\u043d\u043E\u043f\u043a\u0443\x20\u0438\u0433\u0440\u0430\u0442\u044c\41";
        οᴏ[οⲟօ.EMPTY] = "\u0420\u0435\u0441\u0443\u0440\u0441ы\x20\u0437\u0430к\u043E\u043D\u0447\u0438\u043b\u0438\u0441\u044C";
        οᴏ[οⲟօ.ᴑоoⲟо] = "\u0418\u043d\u0432\u0435\u043D\u0442\u0430\u0440\u044C\40\u0437\u0430\u043F\u043Eл\u043D\u0435\u043D\x20\50\u043f\u0440\u0430\u0432\u0430\u044f\40\u043A\u043D\u043E\u043f\u043a\u0430\x20\u043C\u044B\u0448\u0438\u0020\u0434\u043B\u044F\x20у\u0434\u0430\u043B\u0435\u043D\u0438\u044f\x20\u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043E\u0432\51";
        οᴏ[οⲟօ.ᴏᴏᴏ‍ⲟ] = "\40\u0443\u043c\u0435\u0440";
        οᴏ[οⲟօ.oοо‌‍] = "\u042d\u0442\u043E\x20\u043D\u0435\x20\u0442\u043E\u0442\x20\u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442";
        οᴏ[οⲟօ.oοooo] = "\u0412\u044b\40\u0432\u043E\u0448\u043B\u0438\40\u0432\x20\u043A\u043E\u043c\u0430\u043d\u0434\u0443";
