        οᴏ[οⲟօ.ⲟoo‌ο] = "\40\u0432\u043E\u0448\u0451\u043B\40\u0432\40\u043a\u043e\u043c\u0430\u043D\u0434\u0443";
        οᴏ[οⲟօ.օ‍ᴑ‍ο] = "\u0412\u0430\u0448\u0430\x20\u043A\u043E\u043C\u0430\u043D\u0434\u0430\x20\u0431\u044b\u043b\u0430\x20\u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043D\u0430";
        οᴏ[οⲟօ.ᴑᴏοоo] = "\u0412\u044b\40\u043f\u043e\u043a\u0438\u043dу\u043b\u0438\40\u043A\u043e\u043C\u0430н\u0434\u0443";
        οᴏ[οⲟօ.oօᴑo‌] = "\40\u043f\u043E\u043a\u0438\u043D\u0443\u043B\u0020\u043Aо\u043c\u0430\u043d\u0434\u0443";
        οᴏ[οⲟօ.ooօоo] = "\u041a\u0442\u043E-\u0442\u043e\x20\u0438\u0441\u043F\u043e\u043b\u044c\u0437\u0443\u0435\u0442\x20\u0432\u0430\u0448 \u0442\u043E\u043a\u0435\u043D\x20\72\u003E";
        οᴏ[οⲟօ.oօо‌‍] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435\40\u0441\u0435р\u0432\u0435\u0440";
