        οᴏ[οⲟօ.օoᴑᴑ‌] = "\u0438\u0433\u0440\u043E\u043A\u043e\u0432\x20\u0432\u0441\u0435\u0433о";
        οᴏ[οⲟօ.оօᴑᴑo] = "\u0438\u0433\u0440\u043e\u043A\u043E\u0432\40\u0432\40\u044d\u0442\u043E\u043c\40\u0440\u0435\u0436\u0438\u043cе";
