        οoᴏ[0] = ["\u0412\u044b\x20\u0431\u044B\u043b\u0438\40\u0443\u0431\u0438\u0442\u044b\u0020\u0431\u0435\u0437\x20п\u0440\u0438ч\u0438\u043d\u044B"];
        οoᴏ[01] = ["\u0412\u044b\40\u0443\u043c\u0435\u0440\u043B\u0438\40\u043e\u0442\40\u0433\u043e\u043B\u043E\u0434\u0430\x2C\40к\u0430\u043a\u0020\u043d\u0430\u0437\u0432\u0430\u043D\u0438\u0435\x20\u0438\u0433\u0440ы\x20\u043F\u043E\u0434\u0440\u0430\u0437\u0443\u043c\u0435\u0432\u0430\u0435\u0442\40\u044d\u0442\u043e"];
        οoᴏ[02] = ["\u0412\u044B\40\u0437\u0430\u043c\u0435\u0440\u0437\u043b\u0438\x20\u0434\u043e\40\u0441\u043c\u0435\u0440\u0442\u0438\x2E\40\u0422\u0430\u043A\40\u0433\u0440\u0443\u0441\u0442\u043d\u043E", "\u0423\40\u0432\u0430\u0441\40\u0433\u0438\u043f\u043e\u0442\u0435\u0440\u043c\u0438\u044F.\40\u0412\x20\u0441\u043B\u0435\u0434у\u044e\u0449\u0438\u0439\40\u0440\u0430\u0437\54\x20\u043F\u043e\u0441\u0442\u0430\u0440\u0430\u0439\u0442\u0435\u0441\u044C\40\u0431ы\u0442\u044c\x20\u0440\u044F\u0434\u043e\u043c\x20\u0441\x20\u043e\u0433\u043d\u0451\u043C\56"];
        οoᴏ[0X3] = ["\u0418\u0433\u0440\u043E\u043a\x20\u0443\u0431\u0438\u043b\x20\u0442\u0435\u0431\u044F\x20\u0438\40\u0441\u043A\u0430\u0437\u0430\u043b\40\47\u0441\u0442\u0430\u043d\u044C\x20\u043b\u0443\u0447\u0448\u0435\x2e\47", "\u0422\u044B\x20б\u044B\u043b\x20\u0443\u0431\u0438\u0442\x20и\u0433\u0440\u043E\u043a\u043E\u043c\x2e\40\u041d\u0435\40\u0432\u043E\u043B\u043D\u0443\u0439\u0441я\x2c\x20\u044D\u0442о\u0442\x20\u0438\u0433\u0440\u043e\u043a\40\u0442\u043e\u0436\u0435\x20\u0443\u043c\u0440\u0451т\54\u0020\u0432\x20\u043a\u043E\u043D\u0446\u0435\40\u043a\u043E\u043D\u0446\u043e\u0432\x2e"];
        οoᴏ[4] = ["\u0412\u044b\x20\u0441\u0442\u043E\u044f\u043B\u0438\40\u0441\u043B\u0438\u0448\u043aо\u043c\40\u0431\u043B\u0438\u0437\u043A\u043e\x20\u043A\40\u043e\u0433\u043D\u044E\x20\u0438\x20\u0441\u0433\u043E\u0440\u0435\u043b\u0438\56\40\u041f\u043bо\u0445\u0430\u044F\40\u0438\u0434\u0435\u044f\x2e", "\u0422\u044B\x20\u0443\u043c\u0435\u0440\x20\u043E\u0442\40\u043E\u0433\u043d\u044f, \u043eн\40\u043f\u0440\u0438\u0447\u0438\u043D\u0438\u043b\x20\u0432а\u043C\40\u0431\u043Eл\u044C\x2e\40\u041Dа\u043f\u0438\u0448\u0438\u0442\u0435\x20\u0438\u0441\u0442\u043e\u0440\u0438\u044E\x20\u043D\u0430\u0441\u0447\u0451\u0442\x20\u044d\u0442о\u0433\u043E\x2E"];
        οoᴏ[ᴑⲟо] = ["\u0412\u0430\u0448\u0435\40\u0442\u0435\u043b\u043E\40с\u0442\u0430\u043d\u0435\u0442\x20\u0433н\u0435\u0437\u0434\u043e\u043C\40\u0434\u043B\u044f\x20\u044F\u0438\u0446\x20п\u0430\u0443\u043a\u0430", "\u041F\u0430\u0443\u043A\40\u0443\u0431\u0438\u043B\40\u0432\u0430\u0441\x2e\u0020\u041f\u043E\x20\u043A\u0440\u0430\u0439\u043d\u0435\u0439\40\u043c\u0435\u0440\u0435\40\u044d\u0442\u043E\40\u0431\u044b\u043B\u0020\u043d\u0435\40\u043A\u0440\u043e\u043b\u0438\u043a\x2e"];
        οoᴏ[6] = ["\u0412о\u043Bк\40\u0431\u043e\u043b\u044C\u0448\u0435\x20\u043D\u0435 \u0431\u0443\u0434\u0435\u0442\x20\u0433\u043e\u043b\u043e\u0434\u0430\u0442\u044c\u0020\u043F\u043e\u0441\u043b\u0435\40\u0442\u043eг\u043e\54\40к\u0430\u043A\40\u043d\u0430\u0435\u043b\u0441\u044f\40в\u0430\u043C\u0438", "\u041E\u043d\u0438\40н\u0435\u0020\u0441о\u0431\u0430\u043a\u0438\56\x20\u0412\u043e\u043B\u043a\u0438\x20\u043D\u0435\40\u043B\u044E\u0431\u044F\u0442\40\u043B\u0430\u0441к\u0430\u0442\u044C\u0441\u044f\u002E"];
        οoᴏ[7] = ["\u041b\u0438\u0441\u0430\x20\u0431ы\u043b\u0430\x20\u0441\u043B\u0438\u0448\u043a\u043eм\x20\u0431\u044b\u0441\u0442\u0440\u043e\u0439\x20\u0434\u043b\u044F\x20\u0432\u0430\u0441", "\u041b\u0438\u0441\u0430\u0020\u043F\u0440\u0435\u0432\u0440\u0430\u0442и\u043b\u0430\x20\u0442\u0435\u0431\u044F\x20\u0432\x20\u044f\u0449\u0438\u043a\56\40\u0421\x20\u043a\u0430\u043Aи\u0445\40\u043f\u043E\u0440\40\u0436и\u0432\u043E\u0442\u043D\u044B\u0435\40\u043e\u0431\u043B\u0430\u0434\u0430\u044E\u0442\x20\u043Cа\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u043c\u0438\x20\u0441\u043F\u043e\u0441\u043e\u0431\u043D\u043E\u0441\u0442\u044F\u043c\u0438\x3f"];
